// Seeds the IdP the way an admin would: through the core's admin use cases (the idpctl operations) against the same
// local D1 the Worker reads, without the admin Worker's signature gate in between (scenario 11 covers the gate).
// Nothing here is a real secret: the client
// secret and the enroll link are generated by the use cases for this run and live only in the test's memory.
import type { D1Database } from "@cloudflare/workers-types";
import { createD1Database } from "../../packages/d1-adapter/src/index.js";
import { executeOperation, findOperation, type AdminContext, type OperationName } from "../../packages/core/src/admin/index.js";
import { parseIssuer, randomToken } from "../../packages/core/src/shared/index.js";
import { ISSUER } from "./idp.js";

/** The RP stand-in's redirect URI; Chromium maps rp.test to the stand-in's local HTTPS server (support/rp.ts). */
export const REDIRECT_URI = "https://rp.test/callback";

/** A registered client as the RP stand-in knows it. */
export type SeededClient = {
  readonly clientId: string;
  readonly type: "confidential" | "public";
  /** The secret client_create returned once; present only for a confidential client. */
  readonly secret?: string;
};

/** A user with one live enroll link. */
export type SeededUser = {
  readonly userId: string;
  /** `<issuer>/enroll#<token>`, exactly as idpctl would print it. */
  readonly enrollLink: string;
};

/** The admin side of the tests: the idpctl operations a scenario needs, run as one fixed admin. */
export interface Admin {
  /**
   * Creates an enabled user and issues the user's enroll link. Not idempotent: each call makes a new user.
   *
   * @param name The display name.
   * @returns The user's ID and the link.
   * @throws {AdminProblem} user_create or enroll_link_issue refused.
   */
  createUser(name: string): Promise<SeededUser>;
  /**
   * Creates an enabled client whose only redirect URI is {@link REDIRECT_URI}, and grants it to the user.
   *
   * @param type The client type; a confidential client gets a secret.
   * @param userId The user to grant the client to.
   * @returns The client as the RP stand-in needs it.
   * @throws {AdminProblem} client_create or grant_add refused.
   */
  createClient(type: "confidential" | "public", userId: string): Promise<SeededClient>;
  /**
   * Runs user_disable, which also deletes the user's sessions.
   *
   * @param userId The user.
   * @throws {AdminProblem} The user does not exist or is already disabled.
   */
  disableUser(userId: string): Promise<void>;
  /**
   * Runs client_disable; the client's redirect URI is no longer trusted.
   *
   * @param clientId The client.
   * @throws {AdminProblem} The client does not exist or is already disabled.
   */
  disableClient(clientId: string): Promise<void>;
}

/**
 * Builds the admin helpers for a database.
 *
 * @param d1 The IdP's local D1.
 * @returns The helpers.
 */
export function adminFor(d1: D1Database): Admin {
  const ctx: AdminContext = {
    db: createD1Database(d1),
    admin: { name: "e2e", keyid: "e".repeat(64) },
    writerVersion: "admin-worker@e2e",
    now: () => Math.floor(Date.now() / 1000),
    rs256Enabled: false,
    issuer: parseIssuer(ISSUER),
    // A lost failure row would hide why a seed step failed.
    onFailureAuditError: (error) => {
      throw error;
    },
  };

  async function run(name: OperationName, input: unknown): Promise<Readonly<Record<string, unknown>>> {
    const operation = findOperation(name);
    if (operation === undefined) throw new Error(`no admin operation ${name}`);
    const outcome = await executeOperation(ctx, operation, input, { idempotencyKey: randomToken() });
    return outcome.body as Readonly<Record<string, unknown>>;
  }

  return {
    async createUser(name) {
      const { user_id: userId } = await run("user_create", { name });
      const { enrollment_link: enrollLink } = await run("enroll_link_issue", { user_id: userId });
      return { userId: String(userId), enrollLink: String(enrollLink) };
    },
    async createClient(type, userId) {
      const clientId = `${type}-${crypto.randomUUID().slice(0, 8)}`;
      const created = await run("client_create", { client_id: clientId, name: `RP ${clientId}`, client_type: type, redirect_uris: [REDIRECT_URI] });
      await run("grant_add", { client_id: clientId, principal: `user:${userId}` });
      const secret = created["client_secret"];
      return typeof secret === "string" ? { clientId, type, secret } : { clientId, type };
    },
    async disableUser(userId) {
      await run("user_disable", { user_id: userId });
    },
    async disableClient(clientId) {
      await run("client_disable", { client_id: clientId });
    },
  };
}
